import json
import random

def generate_prompt_from_fetched_data(target_word, jsonl_file="examples.jsonl", level="intermediate"):
    examples = []

    try:
        # Safely read the JSONL file generated by fetch.py
        with open(jsonl_file, "r", encoding="utf-8") as f:
            for line in f:
                data = json.loads(line)
                # Ensure case-insensitive matching (e.g., "Bank" == "bank")
                if data["word"].strip().lower() == target_word.strip().lower():
                    examples.append(data["example"])
    except FileNotFoundError:
        # Raise an actual error so the AI doesn't read the error text
        raise FileNotFoundError(f"{jsonl_file} not found. Please run fetch.py first.")

    if not examples:
        raise ValueError(f"No examples found for '{target_word}' in the fetched data.")

    # Pick up to 3 random examples for better variety
    shots = random.sample(examples, min(3, len(examples)))

    formatted_examples = "\n".join(
        [f"{i+1}. {example}" for i, example in enumerate(shots)]
    )

    # ---------------------------------------------------------------------
    # ADVANCED PROMPT ARCHITECTURE (Based on GDEX & CoT Methodologies)
    # ---------------------------------------------------------------------
    
    # The System Prompt establishes the expert persona and strict GDEX rules
    system_instruction = """You are an expert computational lexicographer tasked with generating example sentences for a high-tier language learning dictionary. Your primary objective is to synthesize sentences that perfectly align with the Good Dictionary Example (GDEX) framework.

You must strictly adhere to the following Multi-Objective constraints:
1. length_constraint: The sentence MUST contain strictly between 10 and 15 words. Sentences outside this boundary are unacceptable.
2. vocabulary_constraint: Utilize only high-frequency, everyday vocabulary. Do not use archaic, poetic, or highly specialized terminology unless strictly required by the headword.
3. structural_independence: The sentence MUST NOT contain unresolved pronouns (e.g., he, she, it, they, this, that) or anaphoric references that require external context to understand.
4. collocation_prominence: The target word must act as the primary subject, verb, or object within the main independent clause of the sentence.
5. informativeness: The sentence must provide rich contextual clues that elucidate the meaning of the target word without explicitly defining it."""

    # The User Prompt enforces Chain-of-Thought (CoT) XML formatting
    user_prompt = f"""Generate exactly 5 different example sentences for the word '{target_word}' suitable for an {level} learner.

Reference Dictionary Examples:
{formatted_examples}

OUTPUT FORMAT:
You must utilize Chain-of-Thought reasoning.
Before providing the final sentences, you must open an <analysis> block to verify compliance with the 5 GDEX constraints for each sentence.
After the analysis, provide the sentences within an <example_sentences> block."""

    # This format plugs directly into Mistral's apply_chat_template!
    return [
        {"role": "system", "content": system_instruction},
        {"role": "user", "content": user_prompt}
    ]


if __name__ == "__main__":
    word = input("Enter target word: ")
    
    try:
        messages = generate_prompt_from_fetched_data(word)
        print("\nGenerated Few-Shot Messages for Mistral:\n")
        # Pretty print the dictionary so it's easy to read in the terminal
        print(json.dumps(messages, indent=2))
    except Exception as e:
        print(f"\n❌ Script Stopped: {e}")